// One name and one icon everywhere (brand pass, after CP10b). The name lives in one file,
// src/content/brand.ts, and every place that shows it imports it; the built site in out/ carries
// none of the old names and no "not affiliated" footer; the web manifest, the favicon and the
// apple-touch icon come from the one approved mark (three white bars on the palette's primary),
// generated by scripts/build_app_icons.mjs.
//
// Needs `npm run build` (in web/) first. Run from web/:
//   node --import ./tests/support/register.mjs --test tests/brand.test.mjs

import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { existsSync, mkdtempSync, readFileSync, readdirSync, rmSync, statSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, test } from "node:test";
import { createElement } from "react";
import { renderToString } from "react-dom/server";

// Browser globals the client modules touch, set before the app is imported.
globalThis.window = {
  sessionStorage: { getItem: () => null, setItem: () => {}, removeItem: () => {} },
  location: new URL("https://app.test/"),
};

const { APP_NAME, DISCLAIMER } = await import("../src/content/brand.ts");
const { AppHeader } = await import("../src/components/app-header.tsx");
const { DesktopAppBar } = await import("../src/components/layout/desktop-app-bar.tsx");
const { DesktopFooter } = await import("../src/components/layout/desktop-footer.tsx");
const { buildAllowList } = await import("../scripts/sw_allow_list.mjs");

const WEB = join(import.meta.dirname, "..");
const REPO = join(WEB, "..");
const OUT = join(WEB, "out");
const PUBLIC = join(WEB, "public");
const OLD_NAMES = [/sovereign ledger/i, /m-pesa analytics/i, /m-pesa statement analysis/i];
const TRADEMARK = /m[\s._-]*pesa/i;
const PRIMARY = "#065f46";
const ON_PRIMARY = "#ffffff";
const SURFACE = "#f8fafc";
const TEXT_FILE = /\.(html|txt|js|mjs|css|json|webmanifest|svg|xml)$/;
const SHOWS_THE_NAME = [
  "src/app/layout.tsx",
  "src/app/manifest.ts",
  "src/components/app-header.tsx",
  "src/components/layout/desktop-app-bar.tsx",
  "src/components/layout/desktop-footer.tsx",
  "src/app/page.tsx",
];
const GENERATED_ICONS = [
  ["icon-192.png", 192],
  ["icon-512.png", 512],
  ["icon-maskable-512.png", 512],
  ["apple-touch-icon.png", 180],
];

/** Every file under a directory. */
function filesUnder(directory) {
  return readdirSync(directory).flatMap((name) => {
    const path = join(directory, name);
    return statSync(path).isDirectory() ? filesUnder(path) : [path];
  });
}

/** Rendered markup as visible text, whitespace collapsed. */
function textOf(html) {
  return html.replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim();
}

/** A PNG's width and height, from its IHDR chunk. */
function pngSize(bytes) {
  assert.equal(bytes.subarray(1, 4).toString("latin1"), "PNG", "not a PNG");
  return [bytes.readUInt32BE(16), bytes.readUInt32BE(20)];
}

/** The built web manifest. */
function builtManifest() {
  return JSON.parse(readFileSync(join(OUT, "manifest.webmanifest"), "utf8"));
}

describe("the name", () => {
  test("src/content/brand.ts is the one source: TallyDesk, and the disclaimer built from it", () => {
    assert.equal(APP_NAME, "TallyDesk");
    assert.equal(DISCLAIMER, "TallyDesk is an independent tool and is not affiliated with or endorsed by Safaricom or M-Pesa.");
  });

  test("every file that shows the name imports it from brand.ts and never spells it out", () => {
    for (const file of SHOWS_THE_NAME) {
      const source = readFileSync(join(WEB, file), "utf8");
      assert.match(source, /from "@\/content\/brand"/, `${file} does not import brand.ts`);
      assert.equal(source.includes(APP_NAME), false, `${file} spells the name out`);
    }
  });

  test("the built site holds none of the old names, in any page, script, style or data file", () => {
    const found = [];
    for (const file of filesUnder(OUT).filter((path) => TEXT_FILE.test(path))) {
      const text = readFileSync(file, "utf8");
      for (const name of OLD_NAMES) if (name.test(text)) found.push(`${file.slice(OUT.length)}: ${name}`);
    }
    assert.deepEqual(found, []);
  });

  test("the built pages' title is the name", () => {
    const home = readFileSync(join(OUT, "index.html"), "utf8");
    assert.match(home, new RegExp(`<title>${APP_NAME}</title>`));
  });

  test("the mobile header and the desktop app bar show the name and nothing else as a brand", () => {
    for (const html of [
      renderToString(createElement(AppHeader)),
      renderToString(createElement(DesktopAppBar, { navigation: { tabs: "ingest" } })),
      renderToString(createElement(DesktopAppBar, { navigation: { tabs: "story", importId: null } })),
    ]) {
      assert.ok(textOf(html).includes(APP_NAME), "no name in the header");
      for (const name of OLD_NAMES) assert.doesNotMatch(html, name);
    }
  });

  test("the footer is the name and the year, with no disclaimer", () => {
    const text = textOf(renderToString(createElement(DesktopFooter)));
    assert.equal(text, `${APP_NAME} · © ${new Date().getFullYear()} ${APP_NAME}`);
    assert.doesNotMatch(text, /not affiliated/i);
  });

  test("no built page has a footer saying \"not affiliated\"", () => {
    for (const page of filesUnder(OUT).filter((path) => path.endsWith(".html"))) {
      for (const [footer] of readFileSync(page, "utf8").matchAll(/<footer\b[\s\S]*?<\/footer>/g)) {
        assert.doesNotMatch(footer, /not affiliated/i, page);
      }
    }
  });

  test("the Welcome screen carries the disclaimer, once", () => {
    const html = readFileSync(join(OUT, "index.html"), "utf8").replace(/<script\b[\s\S]*?<\/script>/g, "");
    const text = textOf(html);
    assert.equal(text.split(DISCLAIMER).length - 1, 1);
  });

  test("the README is titled with the name and carries the disclaimer", () => {
    const readme = readFileSync(join(REPO, "README.md"), "utf8");
    assert.equal(readme.split("\n")[0], `# ${APP_NAME}`);
    assert.ok(readme.includes(DISCLAIMER), "README lacks the disclaimer");
    assert.doesNotMatch(readme.split("\n")[0], TRADEMARK);
  });

  test("the service worker's cache is named after the app", () => {
    assert.equal(buildAllowList(OUT).cachePrefix, `${APP_NAME.toLowerCase()}-`);
    const worker = readFileSync(join(PUBLIC, "sw.js"), "utf8");
    assert.match(worker, /const CACHE_PREFIX = LIST\.cachePrefix;/);
  });
});

describe("the web manifest", () => {
  test("is generated from brand.ts (src/app/manifest.ts); public/ holds no hand-written copy", () => {
    assert.ok(existsSync(join(WEB, "src/app/manifest.ts")));
    assert.equal(existsSync(join(PUBLIC, "manifest.webmanifest")), false);
  });

  test("names the app, describes it without the trademark as a name, and uses palette colours", () => {
    const manifest = builtManifest();
    assert.equal(manifest.name, APP_NAME);
    assert.equal(manifest.short_name, APP_NAME);
    assert.equal(manifest.description, "Read your mobile-money statement in this browser and see where the money went.");
    assert.doesNotMatch(manifest.description, TRADEMARK);
    assert.equal(manifest.theme_color, PRIMARY);
    assert.equal(manifest.background_color, SURFACE);
    assert.equal(manifest.start_url, "/");
    assert.equal(manifest.display, "standalone");
  });

  test("lists a 192 and a 512 icon and a maskable 512, each shipped at its stated size", () => {
    const icons = builtManifest().icons;
    const find = (sizes, purpose) => icons.find((icon) => icon.sizes === sizes && (icon.purpose ?? "any") === purpose && icon.type === "image/png");
    for (const [sizes, purpose, side] of [["192x192", "any", 192], ["512x512", "any", 512], ["512x512", "maskable", 512]]) {
      const icon = find(sizes, purpose);
      assert.ok(icon, `no ${purpose} ${sizes} PNG`);
      const file = join(OUT, icon.src);
      assert.ok(existsSync(file), icon.src);
      assert.deepEqual(pngSize(readFileSync(file)), [side, side], icon.src);
    }
  });

  test("every built page links the manifest once", () => {
    const home = readFileSync(join(OUT, "index.html"), "utf8");
    assert.equal(home.match(/rel="manifest"/g)?.length, 1);
    assert.match(home, /<link rel="manifest" href="\/manifest\.webmanifest"/);
  });
});

describe("the icon", () => {
  test("icon.svg and icon-maskable.svg are three bars in on-primary on primary, nothing else", () => {
    for (const name of ["icon.svg", "icon-maskable.svg"]) {
      const svg = readFileSync(join(PUBLIC, name), "utf8");
      const fills = [...svg.matchAll(/fill="([^"]+)"/g)].map(([, fill]) => fill.toLowerCase());
      assert.deepEqual([...new Set(fills)].sort(), [PRIMARY, ON_PRIMARY].sort(), name);
      assert.equal(fills.filter((fill) => fill === ON_PRIMARY).length, 3, `${name}: three bars`);
    }
  });

  test("the PNG icons and favicon.ico are committed, at their sizes", () => {
    for (const [name, side] of GENERATED_ICONS) {
      assert.deepEqual(pngSize(readFileSync(join(PUBLIC, name))), [side, side], name);
    }
    const ico = readFileSync(join(PUBLIC, "favicon.ico"));
    assert.equal(ico.readUInt16LE(0), 0, "ICO reserved field");
    assert.equal(ico.readUInt16LE(2), 1, "ICO type: icon");
    assert.ok(ico.readUInt16LE(4) >= 2, "favicon.ico holds several sizes");
  });

  test("scripts/build_app_icons.mjs regenerates exactly the committed icons from the one source", () => {
    const target = mkdtempSync(join(tmpdir(), "app-icons-"));
    try {
      execFileSync(process.execPath, [join(WEB, "scripts/build_app_icons.mjs"), "--out", target]);
      for (const name of [...GENERATED_ICONS.map(([file]) => file), "favicon.ico"]) {
        assert.ok(readFileSync(join(target, name)).equals(readFileSync(join(PUBLIC, name))), `${name} differs from its source`);
      }
    } finally {
      rmSync(target, { recursive: true, force: true });
    }
  });

  test("@resvg/resvg-js is a dev dependency pinned to an exact version", () => {
    const pkg = JSON.parse(readFileSync(join(WEB, "package.json"), "utf8"));
    assert.match(pkg.devDependencies?.["@resvg/resvg-js"] ?? "", /^\d+\.\d+\.\d+$/);
    assert.equal(pkg.dependencies?.["@resvg/resvg-js"], undefined);
  });

  test("the built pages link the favicon, the SVG icon and the apple-touch icon", () => {
    const home = readFileSync(join(OUT, "index.html"), "utf8");
    assert.match(home, /<link rel="icon" href="\/favicon\.ico"/);
    assert.match(home, /<link rel="icon" href="\/icon\.svg"/);
    assert.match(home, /<link rel="apple-touch-icon" href="\/apple-touch-icon\.png"/);
  });

  test("both headers draw the three-bar mark, not the account_balance glyph", () => {
    const iconPaths = readFileSync(join(WEB, "src/components/icon-paths.ts"), "utf8");
    const glyph = iconPaths.match(/account_balance: \["([^"]+)"/)?.[1];
    for (const html of [
      renderToString(createElement(AppHeader)),
      renderToString(createElement(DesktopAppBar, { navigation: { tabs: "ingest" } })),
    ]) {
      assert.match(html, /data-brand-mark/);
      if (glyph) assert.equal(html.includes(glyph), false, "the account_balance glyph is still drawn");
    }
  });
});
